steps.code:
// Navigate to the URL
const base_url = 'https://news.ycombinator.com/';
let url = new URL(input.url || base_url);

navigate(url);


// Parse the current page to get story URLs
const {urls} = parse();

// Set max_page to 2 if not provided (default to scraping 2 pages)
const max_page = Math.min(input.max_page || 2, 10);

// If this is the first run (not a rerun), trigger reruns for additional pages
if (!input.is_rerun) {
    for (let i = 2; i <= max_page; i++) {
        const next_page_url = new URL(base_url);
        next_page_url.searchParams.set('p', `${i}`);
        rerun_stage({
            url: next_page_url.href,
            max_page: input.max_page,
            is_rerun: true
        });
    }
}

// Collect all URLs from the current page
for (let url of urls) {
    next_stage({url});
}

