    if (story_id) {
        // Construct the Hacker News discussion page URL
        return `https://news.ycombinator.com/item?id=${story_id}`;
    }
    return null;
}).filter(Boolean); // Remove any null/undefined values

console.log(`Found ${urls.length} story discussion URLs on this page`);

return {urls};

