// Navigate to the URL
navigate(input.url);

// Check if we're on a discussion page (item?id=...) where rank is not displayed
// If so, we need to fetch it from the front page or API
const is_discussion_page = location.href.includes('/item?id=');

if (is_discussion_page) {
  // Extract story ID from the discussion page
  const story_id = parse().story_id;

  if (story_id) {
    // Navigate to the front page to find the rank
    navigate('https://news.ycombinator.com/');


    // Parse to get rank from the listing page
    const listing_data = parse();

    // Navigate back to the discussion page to get full details
    navigate(input.url);

    // Parse the discussion page
    const discussion_data = parse();

    // Merge the rank from listing page with discussion page data
    collect({
      ...discussion_data,
      rank: listing_data.rank
    });
  } else {
    // If we can't find story ID, just collect without rank
    collect(parse());
  }
} else {
  // On listing pages, rank is directly available
  collect(parse());
}

parser.parser:
// Extract story ID (useful for discussion pages)
let story_id = $('.fatitem tr[id]').first().attr('id') || $('tr.athing').first().attr('id');

// Extract title and URL from the titleline
let title = $('.titleline > a').text_sane();
let url = $('.titleline > a').attr('href');

// Extract points from the score element
let points_text = $('[id^=score_]').text_sane();
let points = points_text ? +points_text.replace(/\D/g, '') : null;

// Extract author from the subtext
let author = $('.subtext .hnuser').text_sane();

// Extract comment count from the last link in subtext
let comment_text = $('.subtext a:last-child').text_sane();
let comment_count = null;
if (comment_text && comment_text.includes('comment')) {
  comment_count = +comment_text.replace(/\D/g, '');
}

// Extract rank - check if we're on a listing page or need to find it by story_id
let rank = null;
if (story_id) {
  // Try to find rank for this specific story ID
  let rank_text = $(`#${story_id} .rank`).text_sane();
  rank = rank_text ? +rank_text.replace(/\D/g, '') : null;
}

// If rank is still null, try the generic selector (works on listing pages)
if (!rank) {
  let rank_text = $('.rank').first().text_sane();
  rank = rank_text ? +rank_text.replace(/\D/g, '') : null;
}

return {
  story_id: story_id || null,
  title: title || null,
  url: url ? new URL(url) : null,
  points: points,
  author: author || null,
  comment_count: comment_count,
  rank: rank
};

